 xlabel('Time,s'); 
 ylabel('y');
 subplot(2,1,2) 
 plot(f,2*mYdft); % why need *2 ? Bcoz, Hanning Wnd Amplitude Correction Factor = 2
 axis ([0 500 0 5]); %Zoom in 
