w0 = 2*pi ./ (80 + idx/8);
w0 = 20*w0;
x0 = sin( w0 .* idx);
h = hilbert(x0);
N = 10; % filter length of FIR Hilbert transformer is 2*N+1
nn = (1:N)';
g = 2*(sin(pi*nn/2)).^2./ (pi*nn);
g = [-g(N:-1:1);0;g];
hw = hamming(2*N+1);
g = g.*hw(:); % windowed coefficients
I = x0;
Q = filter(g,1,x0);
h2 = I(1:end-N) + 1i*Q(N+1:end);
A1 = abs(h);
A2 = abs(h2);
ph1 = angle(h);
ph2 = angle(h2);
w1 = diff(unwrap(ph1));
w2 = diff ...

